            "<strong>Пример.</strong> Лендинг на 12-колоночной сетке: блок с текстом занимает 7 колонок, блок с изображением — 5 колонок (7+5=12, с учётом gutter). На планшетной ширине сетка переключается на 8 колонок, и то же соотношение текста и изображения пересчитывается в новых пропорциях. Проверка: наложение сетки поверх макета в Figma и визуальная сверка, что все блоки выровнены по колонкам, а не смещены произвольно."
