            "<strong>Пример.</strong> Карточки блога отображаются в 3 колонки на десктопе. При сужении окна до 900px текст в карточках начинает переноситься через слово. Вместо жёсткой привязки к «ширине устройства X» дизайнер добавляет контрольную точку на 960px, при которой сетка переключается на 2 колонки. Проверка: постепенное изменение ширины окна браузера (drag-resize) и фиксация момента, когда контент перестаёт быть комфортным."
