      "d": "Закон Фиттса говорит, что время достижения цели зависит от расстояния до неё и её размера , поэтому часто используемые действия делают крупнее и ближе к текущей точке внимания/руки; закон Хика говорит, что время принятия решения растёт с количеством и сложностью вариантов выбора.",
