            "<strong>Пример.</strong> Меню фильтров интернет-магазина с 25 отдельными чекбоксами в один длинный список против того же набора, сгруппированного в 5 категорий (цена, бренд, размер, цвет, рейтинг) с возможностью развернуть каждую. Тест показывает снижение среднего времени применения первого фильтра при группировке. Проверка: замер времени выполнения задачи «найдите и примените фильтр по цвету» в обоих вариантах."
