            "<strong>Пример.</strong> Форма отправки заявки: ранее кнопка просто становилась неактивной без индикации, и часть пользователей (по логам) нажимала повторно в течение 2 секунд. После добавления анимации загрузки на кнопке (спиннер + текст «Отправляем…») и чёткого финального состояния (галочка + «Отправлено») доля повторных нажатий в логах снизилась. Проверка: сравнение метрики количества повторных нажатий/дублирующих заявок до и после внедрения за сопоставимый период."
