            "<strong>Пример.</strong> Аудит выявил, что токен color-text-secondary (#9E9E9E) на фоне color-surface (#FFFFFF) даёт контраст около 2.8:1 — не проходит AA, и этот токен используется в 40+ местах продукта (подписи под полями, второстепенный текст карточек). Решение — затемнить токен до уровня, проходящего минимум 4.5:1 (например, #707070), и выкатить изменение централизованно через токен, а не точечно. Проверка: повторный автоматический прогон contrast-checker по всем токенам дизайн-системы после изменения."
