            "Нужно показать измеримый разрыв с требованием (конкретный коэффициент контраста против нормы 4.5:1), предложить 2-3 альтернативы, которые сохраняют ощущение бренда (например, более тёмный оттенок того же цвета, увеличенный размер шрифта для перехода в категорию \"крупный текст\", или применение светлого цвета только там, где это не основной читаемый текст), и зафиксировать решение совместно, а не продавливать выбор в одиночку."
