            "<strong>Пример.</strong> Бренд-цвет текста #B0B0B0 на белом фоне: контраст 2.3:1 — не проходит AA (нужно 4.5:1). Альтернатива 1: #767676 на белом — контраст 4.54:1, минимально темнее, визуально близко к бренду. Альтернатива 2: исходный #B0B0B0 оставить только для декоративных крупных заголовков (≥24px), где порог ниже (3:1 всё ещё не проходит, поэтому это не решение само по себе — выбрана альтернатива 1). Решение зафиксировано в дизайн-системе как \"Brand Gray AA\" с пояснением контекста применения."
