            "<strong>Пример.</strong> Матрица приоритизации (вымышленные данные): Находка A: keyboard trap в форме оплаты — серьёзность: высокая, охват: 100% платящих, риск: высокий → Приоритет 1. Находка B: низкий контраст плейсхолдера в системе дизайна (повторяется в 40 местах) — серьёзность: средняя, охват: все формы → Приоритет 2 (один фикс компонента). Находка C: отсутствие alt у декоративной иллюстрации на странице \"О компании\" — серьёзность: низкая, охват: малый → Приоритет 3. Дорожная карта представлена бизнесу как 3 спринта с измеримым прогрессом, а не единоразовый \"аудит на миллион строк\"."
