      "d": "Приоритизация — это осознанный выбор порядка, в котором команда делает задачи, исходя из их ценности и затрат ресурсов; дизайнеру она нужна, чтобы тратить время на решения с наибольшим эффектом для пользователя и бизнеса, а не на то, что просто «громче просят».",
