            "<strong>Пример.</strong> Фича: новый пошаговый онбординг. Goal (цель): пользователи быстрее доходят до первой ценности. Signal (сигнал): завершение ключевого действия в первый день. Metric (метрика): % новых пользователей, выполнивших целевое действие в течение 24 часов после регистрации (измерение Task success и Adoption)."
