            "<strong>Пример.</strong> Приложение для изучения языков, этапы AARRR: Acquisition: установка приложения из рекламы Activation: завершение первого урока (первая ценность) Retention: занятия минимум 3 дня в неделю на 2-й неделе Referral: приглашение друга через встроенный механизм Revenue: оформление платной подписки Дизайн-задача \"улучшить первый урок\" относится к Activation — метрика успеха: % установивших, завершивших первый урок."
