            "Вместо прямого вопроса \"какие у вас требования\", эффективнее спрашивать про контекст: кто конечный пользователь, какую проблему он сейчас решает без продукта, что произойдёт, если задачу не сделать, и какие похожие решения заказчику нравятся или не нравятся и почему — ответы на эти вопросы помогают реконструировать требования, даже если заказчик не умеет формулировать их напрямую."
