            "<strong>Пример.</strong> Заказчик: \"Сделайте раздел отчётов более удобным.\" Вместо \"что значит удобнее?\" дизайнер спрашивает: \"Покажите последний раз, когда вы искали отчёт — что вызвало затруднение?\" \"Какой отчёт вам нужен чаще всего?\" \"Если бы раздел исчез завтра, что сломалось бы в вашей работе в первую очередь?\" Ответы помогают выявить конкретную проблему (например, сложный поиск нужного отчёта среди 200 файлов) вместо абстрактного \"сделать удобнее\"."
