            "<strong>Пример.</strong> Вымышленный случай: агрегированная удовлетворённость новым интерфейсом — 78% (высокая), но 10 \"power user\" клиентов, дающих 35% выручки, жалуются на потерю скорости работы. Действие: сегментация метрик по группе power users отдельно показала падение частоты использования ключевой функции на 20% именно в этом сегменте, хотя у массовой аудитории метрика выросла. Решение: добавить альтернативный \"быстрый режим\" для этого сегмента, сохранив новый интерфейс для массовой аудитории — вместо выбора \"или-или\" между данными и мнением."
