            "<strong>Пример.</strong> В компании с фокусом только на фичи дизайн-лид выявляет, что 18% обращений в поддержку связаны с одной конкретной проблемой устаревшего флоу оплаты. После точечного исправления обращения по этой теме падают на 60% за месяц. Этот кейс используется как основание для выделения 15% капасити каждого спринта под UX- и технический долг на постоянной основе — риск в том, что без этого конкретного измеримого кейса получить согласие могло не получиться вовсе."
