            "<strong>Пример.</strong> Вымышленный случай: сервис подписки выходит на рынок, где преобладает оплата наличными при получении, а не картой онлайн — команда с ограниченным бюджетом проводит 5 интервью с местными пользователями и консультацию с местным партнёром вместо полного исследования рынка. Результат: выявлена критичность локального способа оплаты (она вошла в MVP), но второстепенный вопрос предпочтений по дизайну интерфейса сервиса был решён путём переноса существующего решения без изменений — с явным пониманием риска и планом быстро скорректировать после первых данных."
