            "<strong>Пример.</strong> Вымышленный случай: MVP подписочного сервиса показывает конверсию в оплату 22% (выше ожиданий), но в 6 из 15 отзывов пользователи пишут, что \"не поняли, что оплата произойдёт автоматически после бесплатного периода\". Решение: несмотря на хорошую конверсию, команда приостанавливает масштабирование трафика и сначала добавляет явное напоминание перед списанием — повторяющаяся тема про ощущение обмана сигнализирует о риске для долгосрочного доверия, который не виден в метрике конверсии."
