            "<strong>Пример.</strong> Вымышленный случай: North Star Metric \"количество завершённых задач в неделю\" хорошо отражает ценность для индивидуальных пользователей, но для корпоративных команд реальная ценность — в совместной работе и согласованности, а не в количестве задач на человека. Решение: сохранить общую метрику для отчётности компании, добавить отдельную сегментную метрику \"доля задач с более чем одним участником\" для принятия решений именно по корпоративному направлению продукта."
