      "d": "Однозначно надёжного способа оценить долгосрочный эффект сразу не существует — можно опираться на правдоподобные leading-индикаторы и прошлый опыт похожих изменений, принимая риск ошибки в прогнозе, либо ждать полного цикла для подтверждения, принимая риск отложенного решения в условиях.",
