            "<strong>Пример.</strong> Вымышленный случай: редизайн архитектуры дизайн-системы, ожидаемый эффект на скорость разработки и косвенно на retention — проявится через 2-3 квартала. Контрольные точки: через 1 месяц — скорость сборки новых экранов разработкой (leading-индикатор); через 2 месяца — NPS из пользовательских интервью; через 2 квартала — фактический retention. Решение о продолжении инвестиций пересматривается на каждой контрольной точке, а не только в конце полного цикла."
