            "<strong>Пример.</strong> Вымышленный случай: стартап с запасом финансирования на 6 месяцев рассматривает агрессивный paywall с ограничением бесплатного функционала до минимума, чтобы быстро показать рост выручки инвесторам. Решение: ограниченный по времени (на 2 квартала) более агрессивный, но прозрачный paywall без скрытых условий и манипулятивных формулировок, с чётким планом пересмотра модели монетизации сразу после привлечения следующего раунда финансирования — компромисс зафиксирован как осознанное и временное, а не постоянное решение."
