            "<strong>Пример.</strong> Вымышленный случай: платный контент выделен цветом с контрастом 2.8:1 на фоне (ниже минимума 4.5:1 для обычного текста, WCAG 2.1, критерий 1.4.3, уровень AA), что соответствует дизайн-решению \"сделать бесплатный контент визуально заметно менее привлекательным\". Отчёт дизайнера для руководства: нарушение конкретного критерия WCAG уровня AA, риск жалоб от пользователей с нарушениями зрения, предложенная альтернатива — тот же эффект различения через иконку и подпись \"Premium\" вместо снижения контраста текста."
