            "<strong>Пример.</strong> Вымышленный случай: руководство настаивает на автоматическом продлении платной подписки без предварительного уведомления и с усложнённым процессом отмены. Действие дизайн-лида: предлагает альтернативу — уведомление за 3 дня до списания и отмена в один клик, с оценкой по данным похожих продуктов, что отток от честного уведомления обычно меньше, чем репутационный ущерб от жалоб на скрытое списание. Если руководство всё равно настаивает на исходном варианте, решение и возражение дизайн-команды фиксируются письменно в документации проекта."
