            "<strong>Пример.</strong> Вымышленный случай: предварительно отмеченные галочки согласия на маркетинговые рассылки (нарушение принципа добровольного согласия) обеспечивают 25% базы подписчиков рассылки. A/B-тест с явным, не отмеченным по умолчанию чекбоксом на части аудитории показывает ожидаемое падение подписок на рассылку примерно до 9%. Решение: учитывая прямое несоответствие принципам осознанного согласия, паттерн удаляется полностью и сразу по всей базе, руководству заранее представлен прогноз падения метрики с обоснованием юридического риска сохранения паттерна."
